import {person} from './night-data.js';
import {refundCheckout} from './checkout.js';
export function beginRefusal(g){const s=g.s,a=s.actor,c=person(s,a?.id);if(!a||s.refusal||!c)return false;if(s.transaction?.id===c.id&&s.transaction.stage==='complete')return false;s.refusal={id:c.id,time:0,duration:.95,returnId:s.heldId===c.id||s.trayId===c.id,refund:s.transaction?.id===c.id&&['change','receipt'].includes(s.transaction.stage)?s.transaction.tender:0};a.mode='closing';a.moving=false;a.pausedByTalk=false;s.drawerOpen=false;if(s.refusal.returnId||s.refusal.refund)g.say('你：稍等，我把'+(s.refusal.returnId?'证件':'')+(s.refusal.returnId&&s.refusal.refund?'和':'')+(s.refusal.refund?'付款':'')+'还给你。');if(s.refusal.returnId||s.refusal.refund)g.sound('paper',{pos:a});return true;}
export function settleRefusal(s,id){if(s.refusal?.id!==id)return false;if(s.transaction?.id===id){refundCheckout(s.transaction,s.ledger);s.transaction=null;}for(const key of ['heldId','trayId','idScanned'])if(s[key]===id)s[key]=null;s.idScanRemaining=0;s.refusal=null;return true;}
export function tickRefusal(g,a,dt){const s=g.s,r=s.refusal;if(!r||r.id!==a.id)return false;r.time+=dt;if(r.time<r.duration)return true;const c=person(s,a.id);if(s.transaction?.id===a.id){refundCheckout(s.transaction,s.ledger);s.transaction=null;}if(s.heldId===a.id)s.heldId=null;if(s.trayId===a.id)s.trayId=null;if(s.idScanned===a.id)s.idScanned=null;s.idScanRemaining=0;s.refusal=null;if(!s.denied.includes(c.id)){s.denied.push(c.id);if(c.human)s.mistakes++;}s.actor=a;s.selectedId=a.id;g.depart();g.say(s.frontLocked&&!c.rear&&!c.pump?'证件和付款已结清。前门锁着，请用柜台下的门控按钮解锁，让顾客离开。':c.cn+'：'+(c.human?'好吧，我去下一个站。':'你还会需要我的。'));return true;}
